import { knowledgeBases } from '../data/mockData.js';
import { KBCard } from '../components/KBCard.js';

export class KBList {
  constructor(container) {
    this.container = container;
    this.render();
  }

  render() {
    this.container.innerHTML = `
      <header class="header">
        <h1 class="header-title">知识库管理</h1>
        <div class="header-actions">
          <div class="search-box">
            <input type="text" class="input" placeholder="搜索知识库...">
          </div>
          <button class="btn btn-primary" id="create-kb-btn">
            + 新建知识库
          </button>
        </div>
      </header>

      <div class="content">
        <div class="kb-toolbar">
          <div style="display:flex;gap:8px;">
            <select class="select">
              <option>全部状态</option>
              <option>已启用</option>
              <option>已禁用</option>
            </select>
            <select class="select">
              <option>全部类型</option>
              <option>文档</option>
              <option>网页</option>
              <option>数据库</option>
            </select>
          </div>
          <div style="color:var(--kb-text-muted);font-size:14px;">共 ${knowledgeBases.length} 个知识库</div>
        </div>

        <div class="kb-grid" id="kb-grid"></div>

        <div class="pagination">
          <button class="page-btn" disabled>←</button>
          <button class="page-btn active">1</button>
          <button class="page-btn">2</button>
          <button class="page-btn">3</button>
          <button class="page-btn">→</button>
        </div>
      </div>
    `;

    this.renderKBGrid();
    this.bindEvents();
  }

  renderKBGrid() {
    const gridContainer = document.getElementById('kb-grid');
    gridContainer.innerHTML = '';

    knowledgeBases.forEach((kb) => {
      const cardContainer = document.createElement('div');
      gridContainer.appendChild(cardContainer);

      const card = new KBCard(cardContainer, kb);
      card.setOnClick((kbData) => {
        this.onKBSelect?.(kbData);
      });
      card.setOnAction((action, kbData) => {
        this.onKBAction?.(action, kbData);
      });
    });
  }

  bindEvents() {
    const createBtn = document.getElementById('create-kb-btn');
    if (createBtn) {
      createBtn.addEventListener('click', () => {
        this.onCreateClick?.();
      });
    }

    const searchInput = this.container.querySelector('.search-box input');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this.onSearch?.(e.target.value);
      });
    }
  }

  setOnKBSelect(callback) {
    this.onKBSelect = callback;
  }

  setOnKBAction(callback) {
    this.onKBAction = callback;
  }

  setOnCreateClick(callback) {
    this.onCreateClick = callback;
  }

  setOnSearch(callback) {
    this.onSearch = callback;
  }
}
