export class Modal {
  constructor(id, options = {}) {
    this.id = id;
    this.title = options.title || '';
    this.content = options.content || '';
    this.showCancel = options.showCancel !== false;
    this.showConfirm = options.showConfirm !== false;
    this.cancelText = options.cancelText || '取消';
    this.confirmText = options.confirmText || '确定';
    this.render();
  }

  render() {
    const modalHTML = `
      <div class="modal-overlay" id="${this.id}">
        <div class="modal">
          <div class="modal-header">
            <h3 style="font-size:18px;font-weight:600;">${this.title}</h3>
            <button class="btn btn-circle btn-ghost" data-action="close">✕</button>
          </div>
          <div class="modal-body">${this.content}</div>
          <div class="modal-footer">
            ${this.showCancel ? `<button class="btn btn-secondary" data-action="cancel">${this.cancelText}</button>` : ''}
            ${this.showConfirm ? `<button class="btn btn-primary" data-action="confirm">${this.confirmText}</button>` : ''}
          </div>
        </div>
      </div>
    `;

    const existingModal = document.getElementById(this.id);
    if (existingModal) {
      existingModal.remove();
    }

    document.body.insertAdjacentHTML('beforeend', modalHTML);
    this.bindEvents();
  }

  bindEvents() {
    const overlay = document.getElementById(this.id);
    const buttons = overlay.querySelectorAll('[data-action]');

    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) {
        this.close();
      }
    });

    buttons.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const action = btn.dataset.action;

        switch (action) {
          case 'close':
          case 'cancel':
            this.close();
            this.onCancel?.();
            break;
          case 'confirm':
            this.close();
            this.onConfirm?.();
            break;
        }
      });
    });
  }

  open() {
    document.getElementById(this.id)?.classList.add('active');
  }

  close() {
    document.getElementById(this.id)?.classList.remove('active');
  }

  setContent(content) {
    this.content = content;
    this.render();
  }

  setTitle(title) {
    this.title = title;
    const modal = document.getElementById(this.id);
    if (modal) {
      modal.querySelector('.modal-header h3').textContent = title;
    }
  }

  setOnCancel(callback) {
    this.onCancel = callback;
  }

  setOnConfirm(callback) {
    this.onConfirm = callback;
  }

  destroy() {
    const modal = document.getElementById(this.id);
    if (modal) {
      modal.remove();
    }
  }
}

export class CreateKBModal extends Modal {
  constructor() {
    super('create-modal', {
      title: '新建知识库',
      content: `
        <div class="form-group">
          <label class="form-label">知识库名称</label>
          <input type="text" class="input" id="kb-name" placeholder="输入知识库名称">
        </div>
        <div class="form-group">
          <label class="form-label">描述</label>
          <input type="text" class="input" id="kb-desc" placeholder="简要描述知识库的用途">
        </div>
        <div class="form-group">
          <label class="form-label">类型</label>
          <div class="radio-group">
            <div class="radio-btn active" data-type="文档">📄 文档</div>
            <div class="radio-btn" data-type="网页">🌐 网页</div>
            <div class="radio-btn" data-type="数据库">🗄️ 数据库</div>
            <div class="radio-btn" data-type="问答">💬 问答</div>
          </div>
        </div>
        <div class="form-group">
          <label class="form-label">可见范围</label>
          <select class="select" id="kb-visibility" style="width:100%;">
            <option>私有</option>
            <option>团队可见</option>
            <option>公开</option>
          </select>
        </div>
      `,
      cancelText: '取消',
      confirmText: '创建',
    });

    this.setupFormEvents();
  }

  setupFormEvents() {
    const radioBtns = document.querySelectorAll('#create-modal .radio-btn');
    radioBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        radioBtns.forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });
  }

  getFormData() {
    return {
      name: document.getElementById('kb-name')?.value || '',
      description: document.getElementById('kb-desc')?.value || '',
      type: document.querySelector('#create-modal .radio-btn.active')?.dataset.type || '文档',
      visibility: document.getElementById('kb-visibility')?.value || '私有',
    };
  }
}
